10	import org.springframework.validation.annotation.Validated;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	@Validated
14	public class BuildOwner {
15	
16	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
17	            Out<Boolean> sharesHousehold) {
18	        Owner owner = ownerMapper.toOwner(request);
19	        if (owner.getRegistrationDate() == null) {
20	            owner.setRegistrationDate(LocalDate.now());
21	        }
22	        built.set(owner);
23	        // sharesHousehold is a create-time flag, not an Owner field; republish it for
24	        // RejectDuplicateHousehold. Absent in the body means false.
25	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
26	    }
27	}
