1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Email is optional on an owner. When absent (null or blank) this step does nothing.
11	 * When present it must be a syntactically valid address, otherwise it escalates as a
12	 * 400 via {@link InvalidEmailException}. A valid address is stored back on the owner
13	 * lower-cased (so it is persisted and returned lower-cased).
14	 */
15	public class NormalizeOwnerEmail {
16	
17	    /**
18	     * Pragmatic syntactic check: a non-empty local part, a single '@', then a domain
19	     * with at least one dot and no whitespace.
20	     */
21	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
22	
23	    public void service(@Val Owner owner) throws InvalidEmailException {
24	        String email = owner.getEmail();
25	        if (email == null || email.isBlank()) {
26	            return;
27	        }
28	        String trimmed = email.trim();
29	        if (!EMAIL.matcher(trimmed).matches()) {
30	            throw new InvalidEmailException("Email must be a syntactically valid address");
31	        }
32	        owner.setEmail(trimmed.toLowerCase());
33	    }
34	}
