1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the owner's telephone to E.164 form (see {@link OwnerTelephones}): strip
9	 * spaces, dashes and brackets; keep a leading '+' and country code when present, otherwise
10	 * assume country code '+61' and drop a single leading '0' from the national digits; require
11	 * 8 to 15 digits after the '+'. The E.164 value is stored back on the owner (so it is
12	 * persisted and returned); anything that cannot form a valid E.164 number escalates as a
13	 * 400 via {@link InvalidTelephoneException}.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val Owner owner) throws InvalidTelephoneException {
18	        String e164 = OwnerTelephones.toE164(owner.getTelephone());
19	        if (e164 == null) {
20	            throw new InvalidTelephoneException(
21	                    "Telephone cannot be formatted as a valid E.164 number "
22	                            + "(8 to 15 digits after the country code)");
23	        }
24	        owner.setTelephone(e164);
25	    }
26	}
