5	import org.springframework.samples.petclinic.rest.escalation.InvalidAddressException;
6	
7	/**
8	 * Normalizes the owner's postal address in place (trim and collapse whitespace,
9	 * upper-case, expand common abbreviations) and rejects an address that is blank once
10	 * normalized. Runs before the household steps so duplicate detection and the shared
11	 * household id compare the normalized form.
12	 */
13	public class NormalizeOwnerAddress {
14	
15	    public void service(@Val Owner owner) throws InvalidAddressException {
16	        String normalized = OwnerAddresses.normalize(owner.getAddress());
17	        if (normalized.isBlank()) {
18	            throw new InvalidAddressException("Address must not be blank");
19	        }
20	        owner.setAddress(normalized);
21	    }
22	}
