1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	
8	/**
9	 * Rejects creating an owner whose E.164 telephone is already used by any other owner.
10	 * Runs after {@link NormalizeOwnerTelephone} (so the owner's telephone is already the E.164
11	 * value) and before {@link SaveOwner}. Each stored telephone is converted to E.164 through
12	 * {@link OwnerTelephones} before comparison, so a stored value in any format still collides.
13	 * A match on a different owner escalates as a 409 via {@link DuplicateTelephoneException}.
14	 */
15	public class RejectDuplicateTelephone {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        // The incoming owner's telephone is already E.164 (from NormalizeOwnerTelephone);
20	        // only the stored values (which may predate the pipeline) need converting to compare.
21	        String telephone = owner.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
24	                continue;
25	            }
26	            // A stored value that cannot form valid E.164 yields null, which never matches.
27	            if (telephone.equals(OwnerTelephones.toE164(existing.getTelephone()))) {
28	                throw new DuplicateTelephoneException(
29	                        "Telephone is already used by another owner");
30	            }
31	        }
32	    }
33	}
