1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns a shared {@code householdId} when the request set {@code sharesHousehold} true
13	 * (published by {@link BuildOwner}). A household is defined by {@link HouseholdKey} — the same
14	 * definition {@link RejectDuplicateHousehold} uses to decide who is a duplicate.
15	 *
16	 * <p>The identifier is derived deterministically from the household key, so every owner in a
17	 * household computes the same value and it is stable across requests. It is assigned to this
18	 * (new) owner and also back-filled onto the existing same-household owner(s), so all members
19	 * return the same {@code householdId}.
20	 *
21	 * <p>Does nothing when {@code sharesHousehold} is not true, leaving {@code householdId} absent.
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
26	        if (!Boolean.TRUE.equals(sharesHousehold)) {
27	            return;
28	        }
29	        HouseholdKey household = HouseholdKey.of(owner);
30	        String householdId = householdId(household);
31	        owner.setHouseholdId(householdId);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
34	                continue;
35	            }
36	            if (household.matches(existing) && !householdId.equals(existing.getHouseholdId())) {
37	                existing.setHouseholdId(householdId);
38	                ownerRepository.save(existing);
39	            }
40	        }
41	    }
42	
43	    /** Stable id {@code H-<16 upper-hex>} derived from the household key. */
44	    private static String householdId(HouseholdKey household) {
45	        try {
46	            byte[] digest = MessageDigest.getInstance("SHA-256")
47	                    .digest(household.canonical().getBytes(StandardCharsets.UTF_8));
48	            StringBuilder sb = new StringBuilder();
49	            for (int i = 0; i < 8; i++) {
50	                sb.append(String.format("%02X", digest[i]));
51	            }
52	            return "H-" + sb;
53	        }
54	        catch (NoSuchAlgorithmException ex) {
55	            throw new IllegalStateException("SHA-256 not available", ex);
56	        }
57	    }
58	}
