1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * The single-sourced definition of a normalized postal address, shared by the
8	 * create-time {@link NormalizeOwnerAddress} step (which stores the normalized value)
9	 * and {@link HouseholdKey} (so every address comparison uses the same normalized form).
10	 *
11	 * <p>Normalization trims the value, collapses any run of whitespace to a single space,
12	 * upper-cases it and expands common street-type abbreviations ({@code ST} &rarr;
13	 * {@code STREET}, {@code RD} &rarr; {@code ROAD}, {@code AVE} &rarr; {@code AVENUE}).
14	 */
15	final class OwnerAddresses {
16	
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET",
19	            "RD", "ROAD",
20	            "AVE", "AVENUE");
21	
22	    private OwnerAddresses() {
23	    }
24	
25	    /**
26	     * Normalize an address. Returns {@code ""} when {@code address} is {@code null} or
27	     * is blank once whitespace has been trimmed and collapsed.
28	     */
29	    static String normalize(String address) {
30	        if (address == null) {
31	            return "";
32	        }
33	        String collapsed = address.trim().replaceAll("\\s+", " ");
34	        if (collapsed.isEmpty()) {
35	            return "";
36	        }
37	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
38	        StringBuilder sb = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < tokens.length; i++) {
40	            if (i > 0) {
41	                sb.append(' ');
42	            }
43	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
44	        }
45	        return sb.toString();
46	    }
47	}
